/**
 * Release assets whose URL was not generated by the source instance.
 *
 * Forgejo lets a repository's owner attach a release asset by URL
 * (`external_url`), and only checks that it is a valid URL. Whoever mirrors that
 * repository used to download it with their own source token, from any address,
 * and store the response on their mirror. So the owner of a mirrored repository
 * could collect the token and read internal services without an account here.
 *
 * reconcileReleaseAssets takes the fetch it should use, so no module mocks. IP
 * literals keep the guard away from real DNS.
 */

import { describe, expect, it } from "bun:test";
import { reconcileReleaseAssets, type ReleaseAssetDownloadLimits } from "@/lib/gitea";
import type { Config } from "@/types/config";

const DESTINATION = "https://gitea.example.com";
const ASSETS_URL = `${DESTINATION}/api/v1/repos/mirror-owner/demo/releases/7/assets`;
const SOURCE_TOKEN = "token source-secret";

const config = {
  userId: "user-1",
  giteaConfig: { url: DESTINATION, token: "destination-token" },
} as unknown as Partial<Config>;

interface Download {
  url: string;
  authorization: string | null;
}

type Reply = (signal: AbortSignal) => Response;

function createNetwork(replies: Record<string, Reply> = {}) {
  const downloads: Download[] = [];
  const uploads: string[] = [];
  const signals: AbortSignal[] = [];

  const fetchImpl = (async (input: any, init?: RequestInit) => {
    const url = String(input);
    const method = init?.method ?? "GET";
    if (url === ASSETS_URL && method === "GET") {
      return new Response("[]", { headers: { "content-type": "application/json" } });
    }
    if (url.startsWith(`${ASSETS_URL}?`) && method === "POST") {
      const file = (init!.body as FormData).get("attachment") as Blob;
      uploads.push(await file.text());
      return new Response('{"id":1}', { status: 201 });
    }
    downloads.push({ url, authorization: new Headers(init?.headers).get("authorization") });
    signals.push(init!.signal!);
    const reply = replies[url];
    return reply ? reply(init!.signal!) : new Response("file body");
  }) as unknown as typeof fetch;

  return { fetchImpl, downloads, uploads, signals };
}

function reconcile(
  fetchImpl: typeof fetch,
  asset: { browser_download_url: string; external?: boolean },
  downloadLimits?: ReleaseAssetDownloadLimits
) {
  return reconcileReleaseAssets({
    config,
    decryptedConfig: config as Config,
    repoOwner: "mirror-owner",
    repoName: "demo",
    giteaReleaseId: 7,
    sourceAssets: [{ name: "tool.tar.gz", size: 9, ...asset }],
    downloadAuthorization: SOURCE_TOKEN,
    tagName: "v1",
    fetchImpl,
    downloadLimits,
  });
}

const redirectTo = (location: string) => () =>
  new Response(null, { status: 302, headers: { location } });

/** Headers, then nothing; fails once the request is aborted, like a fetch body. */
const quiet: Reply = (signal) =>
  new Response(
    new ReadableStream({
      start(controller) {
        signal.addEventListener("abort", () => controller.error(signal.reason));
      },
    })
  );

const tightLimits: ReleaseAssetDownloadLimits = {
  source: { stallTimeoutMs: 40 },
  external: { stallTimeoutMs: 40, maxBytes: 4, totalTimeoutMs: 1000 },
};

describe("external release assets", () => {
  it("downloads a public one without the source token", async () => {
    const network = createNetwork();
    const url = "https://1.1.1.1/tool.tar.gz";

    const result = await reconcile(network.fetchImpl, { browser_download_url: url, external: true });

    expect(result).toEqual({ uploaded: 1, failed: 0, skipped: 0 });
    expect(network.downloads).toEqual([{ url, authorization: null }]);
    expect(network.uploads).toEqual(["file body"]);
  });

  it.each([
    "http://169.254.169.254/latest/meta-data/",
    "http://192.168.1.10/router",
    "http://10.0.0.1/",
    "http://127.0.0.1:3000/",
    "http://[::1]/",
  ])("skips %s without sending a request or uploading", async (url) => {
    const network = createNetwork();

    const result = await reconcile(network.fetchImpl, { browser_download_url: url, external: true });

    expect(result).toEqual({ uploaded: 0, failed: 0, skipped: 1 });
    expect(network.downloads).toEqual([]);
    expect(network.uploads).toEqual([]);
  });

  it("skips one that redirects to a private address", async () => {
    const first = "https://1.1.1.1/tool.tar.gz";
    const network = createNetwork({ [first]: redirectTo("http://192.168.1.10/secret") });

    const result = await reconcile(network.fetchImpl, { browser_download_url: first, external: true });

    expect(result).toEqual({ uploaded: 0, failed: 0, skipped: 1 });
    expect(network.downloads.map((download) => download.url)).toEqual([first]);
    expect(network.uploads).toEqual([]);
  });

  it("skips one larger than the cap and closes its request", async () => {
    const network = createNetwork();
    const url = "https://1.1.1.1/tool.tar.gz";

    const result = await reconcile(network.fetchImpl, { browser_download_url: url, external: true }, tightLimits);

    expect(result).toEqual({ uploaded: 0, failed: 0, skipped: 1 });
    expect(network.uploads).toEqual([]);
    expect(network.signals[0].aborted).toBe(true);
  });

  it("skips one that goes quiet", async () => {
    const url = "https://1.1.1.1/tool.tar.gz";
    const network = createNetwork({ [url]: quiet });

    const result = await reconcile(network.fetchImpl, { browser_download_url: url, external: true }, tightLimits);

    expect(result).toEqual({ uploaded: 0, failed: 0, skipped: 1 });
    expect(network.signals[0].aborted).toBe(true);
  });

  it("closes the request when the link answers with an error", async () => {
    const url = "https://1.1.1.1/tool.tar.gz";
    const network = createNetwork({ [url]: () => new Response("gone", { status: 404 }) });

    const result = await reconcile(network.fetchImpl, { browser_download_url: url, external: true });

    expect(result).toEqual({ uploaded: 0, failed: 1, skipped: 0 });
    expect(network.signals[0].aborted).toBe(true);
  });
});

describe("the instance's own release assets", () => {
  it("download with the source token, from a private address too", async () => {
    const network = createNetwork();
    const url = "http://192.168.1.20:3000/attachments/abc";

    const result = await reconcile(network.fetchImpl, { browser_download_url: url });

    expect(result).toEqual({ uploaded: 1, failed: 0, skipped: 0 });
    expect(network.downloads).toEqual([{ url, authorization: SOURCE_TOKEN }]);
  });

  it("keep the token off the storage host a download redirects to", async () => {
    const first = "http://192.168.1.20:3000/attachments/abc";
    const storage = "http://192.168.1.21:9000/bucket/abc?signature=x";
    const network = createNetwork({ [first]: redirectTo(storage) });

    const result = await reconcile(network.fetchImpl, { browser_download_url: first });

    expect(result).toEqual({ uploaded: 1, failed: 0, skipped: 0 });
    expect(network.downloads).toEqual([
      { url: first, authorization: SOURCE_TOKEN },
      { url: storage, authorization: null },
    ]);
  });

  it("are skipped when a download redirects to the metadata address", async () => {
    const first = "http://192.168.1.20:3000/attachments/abc";
    const network = createNetwork({ [first]: redirectTo("http://169.254.169.254/latest/meta-data/") });

    const result = await reconcile(network.fetchImpl, { browser_download_url: first });

    expect(result).toEqual({ uploaded: 0, failed: 0, skipped: 1 });
    expect(network.downloads.map((download) => download.url)).toEqual([first]);
    expect(network.uploads).toEqual([]);
  });

  it("fail when the download goes quiet, so the next sync retries them", async () => {
    const url = "http://192.168.1.20:3000/attachments/abc";
    const network = createNetwork({ [url]: quiet });

    const result = await reconcile(network.fetchImpl, { browser_download_url: url }, tightLimits);

    expect(result).toEqual({ uploaded: 0, failed: 1, skipped: 0 });
    expect(network.signals[0].aborted).toBe(true);
  });

  it("have no size cap", async () => {
    const network = createNetwork();
    const url = "http://192.168.1.20:3000/attachments/abc";

    const result = await reconcile(network.fetchImpl, { browser_download_url: url }, tightLimits);

    expect(result).toEqual({ uploaded: 1, failed: 0, skipped: 0 });
    expect(network.uploads).toEqual(["file body"]);
  });
});
